INSERT INTO public.preloaded_scenes (language_code, art, language, title, description, difficulty, id, slug, media_asset_id, sort_order, content) VALUES (
    'es', 'street', 'Spanish', 'A walk downtown', 'A busy street with a bus, trees and shopfronts.', 'beginner', '22a9958a-2e4b-5022-8aec-38597ddeba0a', 'calle-mayor', 'f9507eb2-776b-4a4f-a6a7-a7c622ff3a16', 0, '{"items": [{"id": "calle", "word": "la calle", "translation": "the street", "wordClass": "noun", "gender": "la", "marker": 1, "x": 18.0, "y": 78.0, "example": "La calle está tranquila hoy.", "exampleTranslation": "The street is quiet today."}, {"id": "autobus", "word": "el autobús", "translation": "the bus", "wordClass": "noun", "gender": "el", "marker": 2, "x": 72.0, "y": 48.0, "example": "El autobús es grande y amarillo.", "exampleTranslation": "The bus is big and yellow."}, {"id": "arbol", "word": "el árbol", "translation": "the tree", "wordClass": "noun", "gender": "el", "marker": 3, "x": 52.0, "y": 40.0, "example": "El árbol está cerca del autobús.", "exampleTranslation": "The tree is near the bus."}, {"id": "grande", "word": "grande", "translation": "big", "wordClass": "adjective", "gender": null, "marker": 4, "x": 86.0, "y": 62.0, "example": "Un edificio grande.", "exampleTranslation": "A big building."}, {"id": "cerca-de", "word": "cerca de", "translation": "near / close to", "wordClass": "preposition", "gender": null, "marker": 5, "x": 38.0, "y": 62.0, "example": "El árbol está cerca de la parada.", "exampleTranslation": "The tree is near the stop."}, {"id": "que-hay", "word": "¿Qué hay en la calle?", "translation": "What is there on the street?", "wordClass": "phrase", "gender": null, "marker": 6, "x": 12.0, "y": 30.0, "example": "¿Qué hay en la calle hoy?", "exampleTranslation": "What is there on the street today?"}], "tasks": [{"id": "t-words", "kind": "word", "title": "Words in this scene", "summary": "3 nouns with audio", "xp": 8, "itemIds": ["calle", "autobus", "arbol"], "note": null}, {"id": "t-gender", "kind": "gender", "title": "Gender tip: la vs el", "summary": "Which article goes with each noun?", "xp": 6, "itemIds": ["calle", "autobus"], "note": "Most nouns ending in -e or -l are masculine (el árbol), and -a endings are usually feminine (la calle). Learn the article together with the word."}, {"id": "t-syntax", "kind": "syntax", "title": "Adjective position", "summary": "café caliente, not caliente café", "xp": 6, "itemIds": ["grande"], "note": "In Spanish the adjective usually comes after the noun: un autobús grande. Putting it first adds emphasis and is rarer in everyday speech."}, {"id": "t-phrase", "kind": "phrase", "title": "Say where things are", "summary": "Use cerca de in a sentence", "xp": 10, "itemIds": ["cerca-de", "que-hay"], "note": null}], "rounds": [{"id": "r1", "clue": "Veo algo grande y amarillo que lleva personas.", "clueTranslation": "I spy something big and yellow that carries people.", "answerId": "autobus", "choices": [{"id": "arbol", "label": "el árbol"}, {"id": "autobus", "label": "el autobús"}, {"id": "calle", "label": "la calle"}, {"id": "coche", "label": "el coche"}], "encouragement": "Nice catch — el autobús is the big yellow one."}, {"id": "r2", "clue": "Veo algo verde que está cerca del autobús.", "clueTranslation": "I spy something green that is near the bus.", "answerId": "arbol", "choices": [{"id": "arbol", "label": "el árbol"}, {"id": "calle", "label": "la calle"}, {"id": "ventana", "label": "la ventana"}, {"id": "autobus", "label": "el autobús"}], "encouragement": "Sí — el árbol is right beside the bus."}, {"id": "r3", "clue": "Veo algo largo donde caminan las personas.", "clueTranslation": "I spy something long where people walk.", "answerId": "calle", "choices": [{"id": "calle", "label": "la calle"}, {"id": "arbol", "label": "el árbol"}, {"id": "autobus", "label": "el autobús"}, {"id": "tienda", "label": "la tienda"}], "encouragement": "La calle — the street you walk on every day."}], "prompts": [{"id": "p1", "itemId": "arbol", "suggestions": ["grande", "verde", "cerca de"], "llmGuess": "¿Es el árbol?", "feedback": "Great clue — grande y verde pointed me straight to el árbol."}, {"id": "p2", "itemId": "autobus", "suggestions": ["amarillo", "grande", "en la calle"], "llmGuess": "¿Es el autobús?", "feedback": "Clear description. Next time try a full sentence: Es grande y amarillo."}]}'
) ON CONFLICT (slug) DO NOTHING;

