    'es', 'cafe', 'Spanish', 'Café de la Plaza', 'Order a coffee and describe what is on the table.', 'beginner', '41f9ad20-bdec-515e-9014-32eb84925d42', 'cafe-plaza', '40e54611-22fb-4a38-977c-f0786df70866', 1, '{"items": [{"id": "cafe", "word": "el café", "translation": "the coffee", "wordClass": "noun", "gender": "el", "marker": 1, "x": 66.0, "y": 45.0, "example": "Un café con leche, por favor.", "exampleTranslation": "A coffee with milk, please."}, {"id": "taza", "word": "la taza", "translation": "the cup", "wordClass": "noun", "gender": "la", "marker": 2, "x": 68.0, "y": 62.0, "example": "La taza está caliente.", "exampleTranslation": "The cup is hot."}, {"id": "mesa", "word": "la mesa", "translation": "the table", "wordClass": "noun", "gender": "la", "marker": 3, "x": 74.0, "y": 74.0, "example": "La taza está sobre la mesa.", "exampleTranslation": "The cup is on the table."}, {"id": "caliente", "word": "caliente", "translation": "hot", "wordClass": "adjective", "gender": null, "marker": 4, "x": 52.0, "y": 36.0, "example": "Un café caliente.", "exampleTranslation": "A hot coffee."}, {"id": "sobre", "word": "sobre", "translation": "on top of", "wordClass": "preposition", "gender": null, "marker": 5, "x": 30.0, "y": 58.0, "example": "El vaso está sobre la mesa.", "exampleTranslation": "The glass is on the table."}], "tasks": [{"id": "c-words", "kind": "word", "title": "Café words", "summary": "3 nouns with audio", "xp": 8, "itemIds": ["cafe", "taza", "mesa"], "note": null}, {"id": "c-gender", "kind": "gender", "title": "Gender tip: la taza / el vaso", "summary": "Two cups, two articles", "xp": 6, "itemIds": ["taza", "cafe"], "note": "La taza (the cup) is feminine, el vaso (the glass) is masculine. Say the article out loud with the noun so it sticks."}, {"id": "c-syntax", "kind": "syntax", "title": "Adjective position", "summary": "café caliente", "xp": 6, "itemIds": ["caliente"], "note": "Describing words follow the noun: café caliente, taza pequeña."}], "rounds":